#!/usr/bin/env bash
# make-fixtures.sh — build the C2paSeal test corpus and its c2patool oracle.
#
#   testdata/unsigned/  originals (generated by scripts/genimages if empty)
#   testdata/signed/    signed by c2patool with the TEST ONLY PKI
#   testdata/broken/    one targeted defect each (scripts/mkbroken + expired signer)
#   testdata/samples/   public C2PA samples, if you put any there (not generated)
#   */*.expected.json   c2patool --detailed output (see scripts/oracle)
#
# Needs: c2patool on PATH, OpenSSL 3.4+, Go, network access to the TSA
# (override with TSA_URL). The expired-signer fixture waits ~90 s for its
# certificate to expire. Run from the repo root.
set -euo pipefail
export MSYS_NO_PATHCONV=1

command -v c2patool >/dev/null || { echo "make-fixtures: c2patool not on PATH" >&2; exit 1; }
[ -f testdata/pki/leaf.pem ] || { echo "make-fixtures: run scripts/make-pki.sh first" >&2; exit 1; }

TSA_URL=${TSA_URL:-http://timestamp.digicert.com}
T=testdata
PKI=$T/pki

# c2patool is a native binary: give it absolute paths, and on Windows
# convert them with cygpath (C:/... form), since path conversion is off.
abs() {
  local p=$1
  case $p in /* | [A-Za-z]:/*) ;; *) p="$PWD/$p" ;; esac
  if command -v cygpath >/dev/null; then cygpath -m "$p"; else echo "$p"; fi
}

# Pin c2patool settings to an empty file so a user's own c2pa.toml cannot
# change the oracle output.
# WORK is in native form (C:/... on Windows) so openssl and c2patool can
# both open files in it.
WORK=$(abs "$(mktemp -d)")
trap 'rm -rf "$WORK"' EXIT
: > "$WORK/settings.toml"
export C2PATOOL_SETTINGS="$WORK/settings.toml"

# manifest <file> <cert-chain> <key> [extra JSON members, each ending in ","]
manifest() {
  cat > "$1" <<EOF
{
  "claim_version": 2,
  "alg": "es256",
  "sign_cert": "$(abs "$2")",
  "private_key": "$(abs "$3")",
  $4
  "claim_generator_info": [{"name": "c2paseal-fixtures", "version": "1.0"}]
}
EOF
}

manifest "$WORK/plain.json" "$PKI/leaf-chain.pem" "$PKI/leaf.key" ""
manifest "$WORK/ts.json" "$PKI/leaf-chain.pem" "$PKI/leaf.key" "\"ta_url\": \"$TSA_URL\","
manifest "$WORK/titled-ts.json" "$PKI/leaf-chain.pem" "$PKI/leaf.key" "
  \"ta_url\": \"$TSA_URL\",
  \"title\": \"C2paSeal titled fixture\",
  \"assertions\": [
    {\"label\": \"stds.schema-org.CreativeWork\", \"data\": {
      \"@context\": \"https://schema.org\", \"@type\": \"CreativeWork\",
      \"author\": [{\"@type\": \"Person\", \"name\": \"C2paSeal Test Author\"}]}}
  ],"
manifest "$WORK/edited.json" "$PKI/leaf-chain.pem" "$PKI/leaf.key" "
  \"assertions\": [
    {\"label\": \"c2pa.actions\", \"data\": {\"actions\": [{\"action\": \"c2pa.color_adjustments\"}]}}
  ],"

# --- unsigned originals -----------------------------------------------------
mkdir -p "$T/unsigned"
if ! ls "$T"/unsigned/*.jpg "$T"/unsigned/*.png >/dev/null 2>&1; then
  go run ./scripts/genimages "$T/unsigned"
fi

# --- signed -----------------------------------------------------------------
rm -rf "$T/signed" "$T/broken"
mkdir -p "$T/signed" "$T/broken"

sign() { # <src> <out> <manifest> [extra c2patool args]
  local src=$1 out=$2 m=$3; shift 3
  c2patool "$src" -m "$(abs "$m")" -o "$out" -f "$@" >/dev/null
  echo "signed: $out"
}

sign "$T/unsigned/small.jpg" "$T/signed/small.jpg"     "$WORK/plain.json"     --create digitalCapture
sign "$T/unsigned/exif.jpg"  "$T/signed/exif.jpg"      "$WORK/plain.json"     --create digitalCapture
sign "$T/unsigned/large.jpg" "$T/signed/large.jpg"     "$WORK/plain.json"     --create digitalCapture
sign "$T/unsigned/small.jpg" "$T/signed/titled-ts.jpg" "$WORK/titled-ts.json" --create digitalCapture
sign "$T/signed/small.jpg"   "$T/signed/edited.jpg"    "$WORK/edited.json"    -p "$T/signed/small.jpg"
sign "$T/unsigned/small.png" "$T/signed/small.png"     "$WORK/plain.json"     --create digitalCapture
sign "$T/unsigned/large.png" "$T/signed/large.png"     "$WORK/plain.json"     --create digitalCapture
sign "$T/unsigned/small.png" "$T/signed/ts.png"        "$WORK/ts.json"        --create digitalCapture

# --- broken -----------------------------------------------------------------
go run ./scripts/mkbroken "$T/signed" "$T/broken"

# Expired signer. c2patool refuses to sign with an already-expired cert, so
# sign with a short-lived one (same test intermediate) and wait it out. No
# timestamp, so validators check the cert against the current time.
utc() { date -u -d "$1" +%Y%m%d%H%M%SZ 2>/dev/null || date -u -v"$2" +%Y%m%d%H%M%SZ; }
openssl genpkey -algorithm EC -pkeyopt ec_paramgen_curve:P-256 -out "$WORK/short.key" 2>/dev/null
openssl req -new -sha256 -key "$WORK/short.key" \
  -subj "/O=C2paSeal TEST ONLY/OU=Not for production/CN=C2paSeal Test Signer (short-lived)" \
  -out "$WORK/short.csr"
cat > "$WORK/leaf.cnf" <<'EOF'
basicConstraints = critical, CA:FALSE
keyUsage = critical, digitalSignature
extendedKeyUsage = emailProtection, 1.3.6.1.5.5.7.3.36
subjectKeyIdentifier = hash
authorityKeyIdentifier = keyid:always
EOF
openssl x509 -req -sha256 -in "$WORK/short.csr" -CA "$PKI/intermediate.pem" -CAkey "$PKI/intermediate.key" \
  -set_serial 0x3003 -not_before "$(utc '-1 day' -1d)" -not_after "$(utc '+90 seconds' +90S)" \
  -extfile "$WORK/leaf.cnf" -out "$WORK/short.pem" 2>/dev/null
cat "$WORK/short.pem" "$PKI/intermediate.pem" > "$WORK/short-chain.pem"
manifest "$WORK/short.json" "$WORK/short-chain.pem" "$WORK/short.key" ""
sign "$T/unsigned/small.jpg" "$T/broken/expired.jpg" "$WORK/short.json" --create digitalCapture
echo "waiting for the short-lived signer to expire..."
sleep 100

# --- oracle -----------------------------------------------------------------
go run ./scripts/oracle "$T"
echo "fixtures done"
